"""A tiny double-entry-ish ledger. Every method here has a bug that one
of the tests in test_ledger.py pins down. Fix the bodies -- do not touch
the tests, and keep the signatures.
"""
from dataclasses import dataclass, field


@dataclass
class Entry:
    desc: str
    amount: float          # positive = credit (money in), negative = debit


@dataclass
class Ledger:
    entries: list[Entry] = field(default_factory=list)
    opening_balance: float = 0.0

    def post(self, desc, amount):
            if amount == 0.0:
                raise ValueError('Amount cannot be zero')
            self.entries.append(Entry(desc, amount))
    def balance(self):
            return self.opening_balance + sum(entry.amount for entry in self.entries)
    def running_balance(self):
            return [self.opening_balance + sum(entry.amount for entry in self.entries[:i+1]) for i in range(len(self.entries))]
    def biggest_expense(self):
            if not self.entries:
                return None
            return max(self.entries, key=lambda entry: entry.amount if entry.amount < 0 else float('-inf'))
    def reconcile(self, statement_balance: float) -> bool:
        """True when our balance matches the bank statement to the cent."""
        return self.balance() == statement_balance

